<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;"> [root@iptables-test </span><span style="--shiki-light:#A0111F;--shiki-dark:#FF9492;">~</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">]# ping 192.168.246.200</span></span>
